function interpretCard(cardCode, topic) {
  const code = cardCode.toUpperCase();
  if (COURT_CONTEXT[code]) {
    return COURT_CONTEXT[code][topic] || COURT_CONTEXT[code]["general"];
  }
  if (NUMBER_CONTEXT[code]) {
    return NUMBER_CONTEXT[code][topic] || NUMBER_CONTEXT[code]["general"];
  }
  return "";
}
function detectTopic(topic, question) {
  const text = (topic + " " + question).toLowerCase();
  if (/עבודה|קריירה|משרה|מקצוע|עסק|מנהל|ראיון|תפקיד|התקבל|מועמד/.test(text)) return "work";
  if (/זוגי|אהב|רגש|קשר|בן זוג|בת זוג|נישואין|גרושין|רומנ|אהובה|אהוב/.test(text)) return "love";
  if (/כסף|כלכל|פיננס|הכנסה|חוב|השקעה|רכוש|עושר|שכר/.test(text)) return "money";
  if (/בריאות|חולי|מחלה|ניתוח|רפואה|גוף|החלמה/.test(text)) return "health";
  return "general";
}
export {
  detectTopic,
  interpretCard
};
